use vstd::prelude::*;

verus! {

    /// Returns an index of a maximum element in a non-empty vector `x`.
    /// Ensures the returned index is in-bounds and the element at that index
    /// is greater than or equal to every other element in `x`.
    fn myfun1(x: &Vec<i32>) -> (max_index: usize)
        requires
            x.len() > 0,
        ensures
            max_index < x.len(),
            forall|j: usize| j < x.len() ==> x[max_index] >= x[j],
    {
        // Initialize max index to 0, and start scanning from i = 1.
        let mut max_idx: usize = 0;
        let mut i: usize = 1;

        // Loop over the rest of the vector to find a maximum.
        while i < x.len()
            invariant
                // i always remains within [0, x.len()]
                i <= x.len(),
                // The recorded max index is always strictly less than i,
                // because we have compared up to i-1.
                max_idx < i,
                // For all positions j that we've scanned so far (j < i),
                // x[max_idx] ≥ x[j].
                forall|j: usize| j < i ==> x[max_idx] >= x[j],
                // The vector remains non-empty.
                x.len() > 0,
            decreases (x.len() - i) as nat,
        {
            // If the current element is strictly greater than the best so far,
            // update the max index. Otherwise, we know x[max_idx] ≥ x[i].
            if x[i] > x[max_idx] {
                max_idx = i;
            } else {
                assert(x[max_idx] >= x[i]);
            }
            i = i + 1;
        }

        // At termination, i == x.len(), so the invariant ensures
        // for all j < x.len(), x[max_idx] ≥ x[j].
        max_idx
    }
}

